# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::ServiceCommandClient do
  # "A refusal or failure raises, which aborts the agent destroy and the user or company destroy that cascades into it"
  # The refusal text must not carry the bearer token, since a company-bound token in a log could be replayed.
  it "raises without the bearer token in its message when Timekeeping refuses the detach credential" do
    base_url = "http://timekeeping.test"
    # Built without a public key, the fake accepts only its own opaque tokens, so it answers 401 to the JWT.
    fake = TimekeepingContract::FakeTimekeeping.new
    route_timekeeping_to_fake(fake, base_url:)
    raised = nil

    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
      described_class.new(base_url:).detach_agent_entries(
        company_id: 5, agent_id: 9, generation: fake.generation, operation_id: SecureRandom.uuid,
        request_id: SecureRandom.uuid
      )
    rescue StandardError => error
      raised = error
    end

    expect(raised).to be_a(Timekeeping::EntryWriteClient::Error)
    sent = fake.requests.first[:headers].find { |name, _value| name.to_s.casecmp?("authorization") }&.last.to_s
    expect(sent).to start_with("Bearer ")
    expect(raised.message).not_to include(sent.delete_prefix("Bearer "))
    expect(raised.message).not_to include("Bearer")
  end
end

RSpec.describe Timekeeping::ServiceCommandClient do
  let(:detach_client_base_url) { "http://timekeeping.test" }

  it "service command client signs the detach with a company-bound detach-only service token" do
    company_id = 4321
    agent_id = 77
    detach_url = "#{detach_client_base_url}/v1/companies/#{company_id}/agents/#{agent_id}/detach-entries"
    captured = {}
    stub_request(:post, detach_url).to_return do |request|
      captured[:authorization] = request.headers["Authorization"].to_s
      captured[:raw] = request.headers.to_s + request.body.to_s
      { status: 200, body: { detached: 3 }.to_json, headers: { "Content-Type" => "application/json" } }
    end

    detached = nil
    with_timekeeping_service_token do |shared_token|
      with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
        detached = described_class.new(base_url: detach_client_base_url).detach_agent_entries(
          company_id:, agent_id:, generation: 1, operation_id: SecureRandom.uuid, request_id: "req-detach-1"
        )
      end
      # "The forwarded call uses a token bound to the agent's company that grants only agents.detach_entries, never TIMEKEEPING_SERVICE_TOKEN"
      expect(captured[:raw]).not_to include(shared_token)
    end

    expect(detached).to eq(3)
    bearer = captured[:authorization].delete_prefix("Bearer ")
    payload, header = JWT.decode(bearer, timekeeping_key_pair.public_key, true, algorithm: "RS256")
    expect(header["alg"]).to eq("RS256")
    expect(payload["typ"]).to eq("timekeeping_service")
    expect(payload["company_id"]).to eq(company_id)
    expect(payload["operations"]).to eq(["agents.detach_entries"])
    expect(payload["sub"]).to be_a(String)
    expect(payload).not_to have_key("role")
    expect(payload).not_to have_key("purpose")
  end
end

RSpec.describe Timekeeping::ServiceCommandClient do
  # "A refusal or failure raises, which aborts the agent destroy and the user or company destroy that cascades into it"
  it "returns zero for a detach that found no entries and raises for a success answer without a detached count" do
    base_url = "http://timekeeping-commands.test"
    url = "#{base_url}/v1/companies/11/agents/22/detach-entries"
    stub_request(:post, url).to_return(
      { status: 200, body: { detached: 0 }.to_json, headers: { "Content-Type" => "application/json" } },
      { status: 200, body: {}.to_json, headers: { "Content-Type" => "application/json" } }
    )

    with_timekeeping_env(Timekeeping::EntryApiClient::BASE_URL_ENV => base_url,
                         Timekeeping::UserToken::PRIVATE_KEY_ENV => timekeeping_key_pair.to_pem) do
      client = described_class.new
      arguments = { company_id: 11, agent_id: 22, generation: 4, operation_id: SecureRandom.uuid, request_id: "req-1" }

      expect(client.detach_agent_entries(**arguments)).to eq(0)
      expect { client.detach_agent_entries(**arguments) }.to raise_error(Timekeeping::EntryWriteClient::Error)
    end
  end
end

RSpec.describe Timekeeping::ServiceCommandClient, "detach refusals" do
  let(:refusal_base_url) { "http://timekeeping-refusals.test" }
  let(:refusal_url) { "#{refusal_base_url}/v1/companies/3/agents/8/detach-entries" }

  def refusal_detach
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
      described_class.new(base_url: refusal_base_url).detach_agent_entries(
        company_id: 3, agent_id: 8, generation: 2, operation_id: "op-refusal", request_id: "req-refusal"
      )
    end
  end

  it "sends operation_id and generation in the body and the request id as X-Request-Id" do
    stub_request(:post, refusal_url).to_return(status: 200, body: { detached: 1 }.to_json)

    expect(refusal_detach).to eq(1)
    expect(WebMock).to have_requested(:post, refusal_url)
      .with(body: { operation_id: "op-refusal", generation: 2 }.to_json, headers: { "X-Request-Id" => "req-refusal" })
  end

  it "raises StaleGeneration for a 409 stale_generation answer" do
    stub_request(:post, refusal_url).to_return(status: 409, body: { reason: "stale_generation" }.to_json)

    expect { refusal_detach }.to raise_error(Timekeeping::Gateway::StaleGeneration)
  end

  [401, 403, 404, 500].each do |status|
    it "raises the retryable client error without the token for a #{status} answer" do
      sent = nil
      stub_request(:post, refusal_url).to_return do |request|
        sent = request.headers["Authorization"].to_s
        { status:, body: { reason: "refused" }.to_json }
      end

      expect { refusal_detach }.to raise_error(Timekeeping::EntryWriteClient::Error) { |error|
        expect(error.message).not_to include(sent.delete_prefix("Bearer "))
      }
    end
  end

  it "raises the retryable client error when Timekeeping times out" do
    stub_request(:post, refusal_url).to_timeout

    expect { refusal_detach }.to raise_error(Timekeeping::EntryWriteClient::Error)
  end

  it "raises the retryable client error when the signing key is missing" do
    stub_request(:post, refusal_url)

    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, nil) do
      expect do
        described_class.new(base_url: refusal_base_url).detach_agent_entries(
          company_id: 3, agent_id: 8, generation: 2, operation_id: "op-refusal", request_id: "req-refusal"
        )
      end.to raise_error(Timekeeping::EntryWriteClient::Error)
    end
    expect(WebMock).not_to have_requested(:post, refusal_url)
  end
end
